<?php defined('_JEXEC') or die; $connections=$items($workspace['connections']??[]); ?>
<div class="dh-page-heading"><div><p class="dh-eyebrow">KNOW YOUR SOURCES</p><h1>Connections</h1><p class="dh-lead">Provider status, retained imports and the path to protected management.</p></div><a class="dh-button" href="<?= $escape($admin . '&section=sources') ?>" target="_blank" rel="noopener noreferrer">Manage in administration <span aria-hidden="true">↗</span></a></div>
