<?php if (!$connections): ?><section class="dh-panel"><p class="dh-empty">No provider information was returned by the backend.</p></section><?php else: ?><div class="dh-provider-grid"><?php foreach ($connections as $provider): $link=$external($provider['registration_url']??$provider['documentation_url']??null); ?>
  <article class="dh-provider"><div class="dh-provider-top"><span class="dh-provider-mark" aria-hidden="true"><?= $escape(mb_substr($provider['name']??'?',0,1)) ?></span><span class="dh-badge"><?= $escape($provider['status']??'Not reported') ?></span></div><h2><?= $escape($provider['name']??$provider['id']??'Provider') ?></h2><p class="dh-muted"><?= $escape($provider['reason']??'No additional status details were supplied.') ?></p><dl class="dh-provider-facts"><div><dt>Retained records</dt><dd><?= $escape($number($provider['record_count']??null)) ?></dd></div><div><dt>Last successful import</dt><dd><?= $escape($date($provider['last_import']??null,true)) ?></dd></div></dl><?php if (!empty($provider['capabilities'])): ?><ul class="dh-tags" aria-label="Provider capabilities"><?php foreach ((array)$provider['capabilities'] as $capability): ?><li><?= $escape(str_replace('_',' ',$capability)) ?></li><?php endforeach; ?></ul><?php endif; ?><div class="dh-provider-action"><?php if ($link): ?><a href="<?= $escape($link) ?>" target="_blank" rel="noopener noreferrer" aria-label="Open <?= $escape($provider['name']??$provider['id']) ?> registration and documentation in a new tab">Registration & documentation <span aria-hidden="true">↗</span></a><?php else: ?><span class="dh-muted">No public documentation address was supplied.</span><?php endif; ?></div></article>
<?php endforeach; ?></div><?php endif; ?>
